// Human Growth & Development Practice Test 1. Original questions written for Valus from the HOSA
// 2026–27 test plan, slightly harder than the sample items: applying theories and milestones to cases.
import {q, mix} from './q.js';
const POL='Polan & Taylor, Journey Across the Lifespan', DHO='Simmers, DHO: Health Science', KATO='Kato, Lifespan Development';
const GOV='Government, Cultural, and Family Influences', THEO='Theories of Development', PRE='Prenatal and Infancy', CHILD='Childhood and Adolescence', ADULT='Adulthood', GERI='Geriatrics, End of Life, and Grief';

export default {
 id:'human-growth-development-1',
 event:'Human Growth & Development',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Polan & Taylor’s Journey Across the Lifespan, Kato’s Lifespan Development, and DHO: Health Science',
 plan:[{area:GOV,weight:20},{area:THEO,weight:16},{area:PRE,weight:12},{area:CHILD,weight:22},{area:ADULT,weight:15},{area:GERI,weight:15}],
 questions:mix([
  q(GOV,'Which federal program provides supplemental foods and nutrition education to low-income pregnant women, infants and children under 5?','WIC',['SNAP','Medicare','Head Start'],'B','The Special Supplemental Nutrition Program for Women, Infants, and Children (WIC) serves pregnant and postpartum women, infants and children up to age 5 who are at nutritional risk.',POL),
  q(GOV,'How do Medicare and Medicaid differ?','Medicare: age 65+; Medicaid: low income',['Medicare: children; Medicaid: adults','Medicare: states; Medicaid: employers','Medicare: dental; Medicaid: vision care'],'D','Medicare is a federal program mainly for people 65 and older and some people with disabilities. Medicaid is a joint federal-state program for people with low incomes.',POL),
  q(GOV,'Which program provides health coverage to children in families that earn too much for Medicaid but cannot afford private insurance?','CHIP',['WIC','TANF','COBRA'],'A','The Children’s Health Insurance Program (CHIP) covers uninsured children in families with modest incomes above the Medicaid limit.',POL),
  q(GOV,'A mother, her new husband, and children from both of their previous marriages live together. What type of family is this?','Blended family',['Nuclear family','Extended family','Single-parent family'],'C','A blended (stepfamily) forms when parents bring children from earlier relationships into a new household. An extended family includes relatives such as grandparents living together.',KATO),
  q(GOV,'A nurse believes her own cultural practices are the right way to handle childbirth and dismisses a family’s traditions. What is this?','Ethnocentrism',['Acculturation','Cultural competence','Assimilation'],'B','Ethnocentrism is the belief that one’s own culture is superior. Cultural competence means respecting and adapting care to patients’ cultural beliefs.',POL),
  q(GOV,'Which parenting style combines high warmth with clear rules and high expectations?','Authoritative',['Authoritarian','Permissive','Uninvolved'],'D','Authoritative parents are warm and responsive but set clear limits and explain them; this style is linked to the best outcomes. Authoritarian parents are strict with little warmth, and permissive parents are warm with few rules.',KATO),
  q(GOV,'Which is an example of a social determinant of health?','Safe, affordable housing',['A person’s blood type','A genetic mutation','A person’s inherited eye color'],'A','Social determinants of health are conditions where people live, learn, work and play, such as housing, education, income and neighborhood safety. They strongly influence health outcomes.',POL),
  q(GOV,'What does the federal Head Start program provide?','Early education and health services for low-income young children',['Free college tuition for first-generation students','Job training and childcare for teenage parents','Prenatal vitamins for pregnant women'],'C','Head Start promotes school readiness for children from birth to age 5 in low-income families through education, health, nutrition and family support services.',KATO),
  q(GOV,'An immigrant family keeps some traditions while adopting many customs of their new country. What is this process called?','Acculturation',['Ethnocentrism','Discrimination','Stereotyping'],'B','Acculturation is the process of adopting some beliefs and behaviors of a new culture while keeping parts of one’s original culture.',POL),
  q(GOV,'What is the purpose of the federal Healthy People initiative?','To set national 10-year health objectives',['To provide health insurance to all citizens','To license healthcare professionals','To fund hospital construction'],'D','Healthy People sets measurable national health objectives every decade (currently Healthy People 2030) to guide prevention and reduce health disparities.',POL),
  q(THEO,'According to Erikson, what is the central conflict of adolescence?','Identity vs. role confusion',['Industry vs. inferiority','Intimacy vs. isolation','Autonomy vs. shame and doubt'],'A','Adolescents work to form a clear sense of who they are and their values and goals. Industry vs. inferiority is school age, and intimacy vs. isolation is young adulthood.',KATO),
  q(THEO,'A 2-year-old insists, “Me do it!” when getting dressed. Which Erikson stage does this behavior reflect?','Autonomy vs. shame and doubt',['Trust vs. mistrust','Initiative vs. guilt','Industry vs. inferiority'],'C','Toddlers seek independence in self-care. Encouraging safe choices builds autonomy; excessive criticism leads to shame and doubt.',KATO),
  q(THEO,'A 4-year-old believes a tall, thin glass holds more juice than a short, wide glass with the same amount. Which Piaget stage explains this?','Preoperational',['Sensorimotor','Concrete operational','Formal operational'],'B','In the preoperational stage (about ages 2–7), children have not yet mastered conservation, the understanding that quantity stays the same when shape changes.',KATO),
  q(THEO,'Which ability first appears in Piaget’s formal operational stage?','Reasoning about abstract and hypothetical ideas',['Understanding that objects still exist when hidden','Using symbols and pretend play','Understanding conservation of volume'],'D','Formal operational thought, beginning around age 11–12, allows abstract, logical and hypothetical reasoning. Object permanence develops in infancy, and conservation in the concrete operational stage.',KATO),
  q(THEO,'According to Maslow’s hierarchy of needs, which need must generally be met first?','Physiological needs',['Safety and security','Love and belonging','Self-actualization and purpose'],'A','Maslow’s base level is physiological survival needs. Higher needs (safety, belonging, esteem, self-actualization) become motivating as lower needs are met.',DHO),
  q(THEO,'A child says she will not take a cookie because she would get punished. Which of Kohlberg’s levels does this reasoning reflect?','Preconventional',['Conventional','Postconventional','Formal operational'],'C','At the preconventional level, moral decisions are based on avoiding punishment or gaining rewards. Conventional reasoning focuses on social rules and approval.',KATO),
  q(THEO,'According to Vygotsky, the zone of proximal development is:','What a child can do with help but not yet alone',['The age at which language first appears','The part of the brain that controls learning','The stage when a child reasons abstractly'],'B','Vygotsky described the gap between independent ability and what a learner can achieve with guidance. Support within this zone is called scaffolding.',KATO),
  q(THEO,'An 8-month-old searches under a blanket for a toy he watched being hidden. Which concept has he developed?','Object permanence',['Conservation','Egocentrism','Reversibility'],'D','Object permanence, part of Piaget’s sensorimotor stage, is understanding that objects still exist when they cannot be seen.',KATO),
  q(PRE,'During which prenatal period are the major organs forming, making the developing child most vulnerable to teratogens?','The embryonic period (weeks 3–8)',['The germinal period (weeks 1–2)','The fetal period (weeks 9–40)','The final month of pregnancy'],'C','Organogenesis occurs during the embryonic period, so exposure to teratogens such as alcohol, some drugs and infections then is most likely to cause major birth defects.',POL),
  q(PRE,'Which syndrome results from alcohol use during pregnancy and can cause facial abnormalities and intellectual disability?','Fetal alcohol syndrome',['Down syndrome','Neonatal abstinence syndrome','Sudden infant death syndrome'],'A','Alcohol is a teratogen; no amount is known to be safe in pregnancy. Neonatal abstinence syndrome is withdrawal after birth from drugs such as opioids.',POL),
  q(PRE,'A loud noise makes a newborn fling out the arms and then bring them inward. Which reflex is this?','Moro reflex',['Rooting reflex','Babinski reflex','Palmar grasp reflex'],'B','The Moro (startle) reflex normally disappears by about 4–6 months. The rooting reflex turns the head toward a touch on the cheek.',POL),
  q(PRE,'By about what age does a healthy infant usually triple their birth weight?','12 months',['3 months','6 months','24 months'],'D','Infants typically double their birth weight by about 5–6 months and triple it by about 1 year.',POL),
  q(PRE,'An infant gains head control before learning to sit and later to walk. Which principle of development does this illustrate?','Cephalocaudal development',['Proximodistal development','Gross-to-fine development','Simple-to-complex development'],'C','Cephalocaudal development proceeds from head to toe. Proximodistal development proceeds from the center of the body outward, such as arm control before finger control.',POL),
  q(PRE,'The anterior fontanel usually closes at what age?','12 to 18 months',['2 to 3 months','4 to 6 months','3 to 4 years'],'A','The posterior fontanel closes by about 2–3 months and the larger anterior fontanel by about 12–18 months. A bulging or sunken fontanel can signal illness.',POL),
  q(CHILD,'Two toddlers sit side by side, each playing with their own blocks without interacting. What type of play is this?','Parallel play',['Cooperative play','Associative play','Solitary play'],'B','Parallel play is typical of toddlers: children play near each other with similar toys but not together. Cooperative play, with shared goals and roles, develops in later childhood.',POL),
  q(CHILD,'A 9-year-old understands that a ball of clay flattened into a pancake still has the same amount of clay. Which Piaget stage is she in?','Concrete operational',['Preoperational','Sensorimotor','Formal operational'],'D','Concrete operational children (about ages 7–11) understand conservation and reversibility and think logically about concrete objects.',KATO),
  q(CHILD,'Which statement about the timing of puberty is correct?','Girls usually begin puberty about two years earlier than boys',['Boys usually begin puberty about two years earlier than girls','Boys and girls begin puberty at exactly the same age','Puberty usually begins after age 16'],'A','Puberty typically starts around ages 8–13 in girls and 9–14 in boys. Menarche usually occurs about 2–3 years after breast development begins.',KATO),
  q(CHILD,'What is the leading cause of death among U.S. adolescents?','Unintentional injuries',['Cancer','Heart disease','Infectious diseases such as influenza'],'C','Unintentional injuries, led by motor vehicle crashes, cause the most deaths among adolescents, followed by suicide and homicide.',POL),
  q(CHILD,'At what age is the first dose of the MMR vaccine usually given?','12 to 15 months',['At birth','2 months','4 to 6 years'],'B','The first MMR dose is given at 12–15 months and the second at 4–6 years. Maternal antibodies can interfere with the vaccine if it is given too early.',POL),
  q(CHILD,'How is obesity defined for children and teens?','BMI at or above the 95th percentile',['BMI above 25 regardless of age','A weight above 100 pounds by age 10','BMI at or above the 50th percentile'],'D','Because body fat changes as children grow, BMI is compared with growth charts. The 85th to 95th percentile is overweight, and the 95th percentile or above is obesity.',POL),
  q(CHILD,'A 14-year-old refuses to go to school with a small pimple, convinced everyone will stare at it. Which concept describes this?','Imaginary audience',['Personal fable','Identity foreclosure','Object permanence'],'A','Adolescent egocentrism includes the imaginary audience, the belief that others are always watching, and the personal fable, the belief that one is unique or invulnerable.',KATO),
  q(CHILD,'Why are young children living in homes built before 1978 at special risk for lead poisoning?','Old lead paint chips and dust can be swallowed',['These homes have no smoke detectors','The water in old homes contains fluoride','Older homes usually contain more toxic mold'],'C','Lead paint was banned in 1978. Young children put hands and objects in their mouths and absorb lead more readily, which can harm brain development.',POL),
  q(CHILD,'Why do many teenagers naturally fall asleep and wake later than younger children?','Puberty shifts the body’s circadian rhythm later',['Teens need less sleep than children','Melatonin stops being produced in adolescence','Homework is the only cause of later bedtimes'],'B','During puberty, melatonin is released later at night, shifting the sleep cycle. Teens still need about 8–10 hours of sleep.',POL),
  q(CHILD,'Why are adolescents more prone to risk-taking than adults?','The prefrontal cortex is still maturing',['The brain stops growing at age 12','Adolescents have fully developed impulse control','Hormones permanently damage judgment'],'D','The prefrontal cortex, which handles planning and impulse control, keeps developing into the mid-20s, while reward systems mature earlier.',KATO),
  q(CHILD,'In DHO, which developmental task is emphasized during the school-age years (6–12)?','Building friendships and a sense of accomplishment',['Establishing a career and starting a family','Forming a first attachment to caregivers','Adjusting to retirement'],'A','School-age children develop friendships, skills and self-esteem through achievement, consistent with Erikson’s industry vs. inferiority.',DHO),
  q(ADULT,'According to Erikson, what is the main challenge of young adulthood?','Intimacy vs. isolation',['Generativity vs. stagnation','Integrity vs. despair','Identity vs. role confusion'],'C','Young adults seek close, committed relationships. Failure can lead to isolation.',KATO),
  q(ADULT,'A 50-year-old mentors younger coworkers and volunteers in her community. Which Erikson stage does this reflect?','Generativity vs. stagnation',['Intimacy vs. isolation','Integrity vs. despair','Industry vs. inferiority'],'B','In middle adulthood, generativity means contributing to the next generation through parenting, mentoring, work and community.',KATO),
  q(ADULT,'A middle-aged adult cares for teenage children and aging parents at the same time. What is this group often called?','The sandwich generation',['The empty nest generation','The baby boom generation','The lost generation'],'D','Caring for both children and older parents can cause financial strain and caregiver stress.',POL),
  q(ADULT,'What causes the symptoms of menopause?','Declining estrogen from the ovaries',['An increase in progesterone production','A sudden rise in testosterone','A decrease in thyroid hormone'],'A','Menopause, on average around age 51, occurs when the ovaries stop releasing eggs and produce less estrogen, causing hot flashes and increasing bone loss.',POL),
  q(ADULT,'A 45-year-old must hold a menu at arm’s length to read it. What is this age-related change called?','Presbyopia',['Myopia','Astigmatism','Glaucoma'],'C','Presbyopia is the gradual loss of the lens’s ability to focus up close, usually noticed in the 40s. Myopia is nearsightedness.',POL),
  q(ADULT,'By about what age do most people reach their peak bone mass?','About 30',['About 15','About 45','About 60'],'B','Bone mass peaks around age 30; after that, bone breakdown slowly exceeds formation. Building bone in youth lowers osteoporosis risk later.',POL),
  q(ADULT,'Parents feel sad and lonely after their last child moves out. What is this commonly called?','Empty nest syndrome',['Sandwich generation stress','Midlife identity foreclosure','Generativity crisis'],'D','Empty nest syndrome describes the grief some parents feel when children leave home. Many parents also find new freedom and closer partner relationships.',KATO),
  q(GERI,'What is the order of Kübler-Ross’s five stages of grief?','Denial, anger, bargaining, depression, acceptance',['Anger, denial, depression, bargaining, acceptance','Denial, bargaining, anger, acceptance, depression','Shock, anger, depression, bargaining, acceptance'],'A','Kübler-Ross described denial, anger, bargaining, depression and acceptance. People may move back and forth between stages.',DHO),
  q(GERI,'An 80-year-old reflects on his life with satisfaction and peace. Which Erikson stage has he resolved successfully?','Integrity vs. despair',['Generativity vs. stagnation','Intimacy vs. isolation','Trust vs. mistrust'],'C','In late adulthood, people review their lives. Integrity is acceptance of one’s life; despair is regret and fear of death.',KATO),
  q(GERI,'Who is generally eligible for hospice care?','A terminally ill person expected to live 6 months or less',['Any older adult who lives alone','A person recovering at home from major surgery','A person who needs physical therapy'],'B','Hospice provides comfort-focused care for people who are no longer seeking a cure and have a prognosis of about 6 months or less.',POL),
  q(GERI,'How does palliative care differ from hospice care?','It can be given alongside curative treatment',['It is only given in the final days of life','It is only for patients who have cancer','It replaces all other medical treatment'],'D','Palliative care relieves symptoms and stress for anyone with a serious illness, even while treatment continues. Hospice is palliative care at the end of life.',POL),
  q(GERI,'A hiring manager assumes an older applicant cannot learn new technology. What is this an example of?','Ageism',['Ethnocentrism','Sarcopenia','Sundowning'],'A','Ageism is stereotyping or discrimination based on age. It can lead to older adults being overlooked for jobs or receiving less aggressive care.',POL),
  q(GERI,'A resident with dementia becomes more confused and agitated in the late afternoon and evening. What is this called?','Sundowning',['Delirium tremens','Postictal confusion','Learned helplessness'],'C','Sundowning is increased confusion and agitation later in the day in people with dementia. Consistent routines and good lighting can help.',DHO),
  q(GERI,'Which term describes the gradual, age-related loss of muscle mass and strength?','Sarcopenia',['Osteopenia','Kyphosis','Atrophic gastritis'],'B','Sarcopenia raises the risk of falls and disability. Resistance exercise and adequate protein help slow it. Osteopenia is low bone density.',POL),
  q(GERI,'Which sign suggests that death is approaching?','Deep breaths alternating with pauses',['A sudden increase in appetite','Warm, pink skin on the hands and feet','An increase in urine output'],'D','Near death, breathing may follow a Cheyne-Stokes pattern, the skin becomes cool and mottled, and urine output decreases. Hearing is thought to be the last sense lost.',DHO)
 ],37)
};
